-- Israel Reference canonical-name migration.
-- Generated by tools/build_israel_reference_name_migration.py from the live catalog.
-- Updates only display names on Global Models and their IL Listings.
-- Raw source evidence, prices, Family, Pricing Key and purchase formats are untouched.

begin;

create temporary table _canonical_name_seed (
    material_model_code text primary key,
    canonical_name text not null
) on commit drop;


update public.reference_material_models model
set canonical_name = seed.canonical_name, updated_at = now()
from _canonical_name_seed seed
where model.material_model_code = seed.material_model_code
  and model.active;

update public.reference_market_material_listings listing
set canonical_market_name = model.canonical_name, updated_at = now()
from public.reference_material_models model
where listing.market_code = 'IL'
  and listing.active
  and listing.material_model_id = model.material_model_id;

do $$
declare
    mismatches integer;
    missing integer;
begin
    select count(*) into missing
    from _canonical_name_seed seed
    left join public.reference_material_models model on model.material_model_code = seed.material_model_code and model.active
    where model.material_model_id is null;
    if missing <> 0 then
        raise exception 'Canonical-name migration did not update % active models', missing;
    end if;
    select count(*) into mismatches
    from public.reference_market_material_listings listing
    join public.reference_material_models model on model.material_model_id = listing.material_model_id
    where listing.market_code = 'IL' and listing.active and listing.canonical_market_name <> model.canonical_name;
    if mismatches <> 0 then
        raise exception 'Global Model and Israel Listing names diverged for % rows', mismatches;
    end if;
end $$;

commit;
